<?php
namespace RoutesPro\Admin;

use RoutesPro\Integrations\ApiKeyService;
use RoutesPro\Integrations\WebhookService;
use RoutesPro\Integrations\PublicQueryService;

if(!defined('ABSPATH'))exit;

class PublicIntegrations {
    public const SLUG='routespro-public-integrations';
    public static function registerHooks():void{
        add_action('admin_post_fieldflow_api_key_create',[self::class,'createKey']);
        add_action('admin_post_fieldflow_api_key_revoke',[self::class,'revokeKey']);
        add_action('admin_post_fieldflow_webhook_create',[self::class,'createWebhook']);
        add_action('admin_post_fieldflow_webhook_action',[self::class,'webhookAction']);
    }
    private static function guard(string$action):void{if(!current_user_can('routespro_manage'))wp_die('Sem permissões.');check_admin_referer($action);}
    private static function redirect(array$args=[]):void{wp_safe_redirect(add_query_arg($args,admin_url('admin.php?page='.self::SLUG)));exit;}
    public static function createKey():void{self::guard('fieldflow_api_key_create');$result=ApiKeyService::create($_POST,get_current_user_id());if(!empty($result['key'])){set_transient('fieldflow_api_key_once_'.get_current_user_id(),$result['key'],300);self::redirect(['created'=>'key']);}self::redirect(['error'=>sanitize_text_field((string)($result['error']??'Não foi possível criar a chave.'))]);}
    public static function revokeKey():void{self::guard('fieldflow_api_key_revoke');ApiKeyService::revoke(absint($_POST['id']??0));self::redirect(['updated'=>'key']);}
    public static function createWebhook():void{self::guard('fieldflow_webhook_create');$clientId=absint($_POST['client_id']??0);if($clientId&&class_exists('RoutesPro\\SaaS\\EntitlementService')&&!\RoutesPro\SaaS\EntitlementService::clientHas($clientId,'webhooks.manage'))self::redirect(['error'=>'Os webhooks não estão incluídos no plano deste cliente.']);$result=WebhookService::create($_POST,get_current_user_id());if(!empty($result['secret'])){set_transient('fieldflow_webhook_secret_once_'.get_current_user_id(),$result['secret'],300);self::redirect(['created'=>'webhook']);}self::redirect(['error'=>sanitize_text_field((string)($result['error']??'Não foi possível criar o webhook.'))]);}
    public static function webhookAction():void{self::guard('fieldflow_webhook_action');$id=absint($_POST['id']??0);$action=sanitize_key((string)($_POST['do']??''));if($action==='test')WebhookService::test($id);elseif($action==='retry')WebhookService::retry($id);elseif(in_array($action,['active','paused','revoked'],true))WebhookService::setStatus($id,$action);self::redirect(['updated'=>'webhook']);}
    public static function render():void{
        if(!current_user_can('routespro_manage'))wp_die('Sem permissões.');global$wpdb;$clients=$wpdb->get_results('SELECT id,name FROM '.$wpdb->prefix.'routespro_clients ORDER BY name',ARRAY_A)?:[];$projects=$wpdb->get_results('SELECT id,client_id,name FROM '.$wpdb->prefix.'routespro_projects ORDER BY name',ARRAY_A)?:[];$keys=ApiKeyService::rows();$hooks=WebhookService::hooks();$deliveries=WebhookService::deliveries();$onceKey=get_transient('fieldflow_api_key_once_'.get_current_user_id());$onceSecret=get_transient('fieldflow_webhook_secret_once_'.get_current_user_id());delete_transient('fieldflow_api_key_once_'.get_current_user_id());delete_transient('fieldflow_webhook_secret_once_'.get_current_user_id());$base=rest_url('fieldflow-public/v1');
        ?>
        <div class="wrap"><h1>API Pública e Webhooks</h1><?php if(!empty($_GET['error'])):?><div class="notice notice-error"><p><?php echo esc_html(sanitize_text_field(wp_unslash((string)$_GET['error'])));?></p></div><?php endif;?><p>Liga o FieldFlow a Power BI, ERP, CRM e automações externas com isolamento por cliente, projeto e capacidade.</p>
        <?php if($onceKey):?><div class="ff-secret"><strong>Guarda esta chave agora.</strong> Só é mostrada uma vez.<div class="ff-code"><?php echo esc_html($onceKey);?></div></div><?php endif;?>
        <?php if($onceSecret):?><div class="ff-secret"><strong>Segredo de assinatura do webhook.</strong> Guarda-o no sistema destinatário.<div class="ff-code"><?php echo esc_html($onceSecret);?></div></div><?php endif;?>
        <div class="ff-int-grid">
        <div class="ff-int-card"><h2>Nova chave API</h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><?php wp_nonce_field('fieldflow_api_key_create');?><input type="hidden" name="action" value="fieldflow_api_key_create"><table class="form-table"><tr><th>Nome</th><td><input name="name" class="regular-text" required></td></tr><tr><th>Cliente</th><td><select name="client_id"><option value="0">Global, apenas administração</option><?php foreach($clients as$c):?><option value="<?php echo(int)$c['id'];?>"><?php echo esc_html($c['name']);?></option><?php endforeach;?></select></td></tr><tr><th>Projeto</th><td><select name="project_id"><option value="0">Todos no cliente</option><?php foreach($projects as$p):?><option value="<?php echo(int)$p['id'];?>"><?php echo esc_html($p['name']);?></option><?php endforeach;?></select></td></tr><tr><th>Capacidades</th><td><?php foreach(ApiKeyService::capabilityCatalog()as$k=>$label):?><label style="display:block;margin:5px 0"><input type="checkbox" name="capabilities[]" value="<?php echo esc_attr($k);?>"> <?php echo esc_html($label);?></label><?php endforeach;?></td></tr><tr><th>IP permitidos</th><td><textarea name="allowed_ips" rows="3" class="large-text" placeholder="203.0.113.10, 10.0.0.0/24"></textarea></td></tr><tr><th>Pedidos por minuto</th><td><input type="number" name="rate_limit_per_minute" value="120" min="10" max="5000"></td></tr><tr><th>Expira em</th><td><input type="datetime-local" name="expires_at"></td></tr></table><button class="button button-primary">Criar chave protegida</button></form></div>
        <div class="ff-int-card"><h2>Novo webhook</h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><?php wp_nonce_field('fieldflow_webhook_create');?><input type="hidden" name="action" value="fieldflow_webhook_create"><table class="form-table"><tr><th>Nome</th><td><input name="name" class="regular-text" required></td></tr><tr><th>URL</th><td><input type="url" name="url" class="large-text" required placeholder="https://example.com/webhooks/fieldflow"></td></tr><tr><th>Cliente</th><td><select name="client_id"><option value="0">Todos</option><?php foreach($clients as$c):?><option value="<?php echo(int)$c['id'];?>"><?php echo esc_html($c['name']);?></option><?php endforeach;?></select></td></tr><tr><th>Projeto</th><td><select name="project_id"><option value="0">Todos</option><?php foreach($projects as$p):?><option value="<?php echo(int)$p['id'];?>"><?php echo esc_html($p['name']);?></option><?php endforeach;?></select></td></tr><tr><th>Eventos</th><td><?php foreach(WebhookService::eventCatalog()as$k=>$label):?><label style="display:block;margin:5px 0"><input type="checkbox" name="events[]" value="<?php echo esc_attr($k);?>"> <?php echo esc_html($label);?></label><?php endforeach;?></td></tr><tr><th>Tentativas</th><td><input type="number" name="max_attempts" value="6" min="1" max="12"></td></tr></table><button class="button button-primary">Criar webhook</button></form></div>
        </div>
        <div class="ff-int-card"><h2>Chaves API</h2><div class="ff-scroller"><table class="widefat striped"><thead><tr><th>Nome</th><th>Âmbito</th><th>Prefixo</th><th>Capacidades</th><th>Último uso</th><th>Estado</th><th></th></tr></thead><tbody><?php if(!$keys):?><tr><td colspan="7">Ainda não existem chaves.</td></tr><?php else:foreach($keys as$k):$caps=json_decode((string)$k['capabilities_json'],true);?><tr><td><?php echo esc_html($k['name']);?></td><td>C<?php echo(int)$k['client_id'];?> / P<?php echo(int)$k['project_id'];?></td><td><code><?php echo esc_html('ffpk_'.$k['id'].'_'.$k['key_prefix'].'...');?></code></td><td><?php echo esc_html(implode(', ',(array)$caps));?></td><td><?php echo esc_html((string)($k['last_used_at']?:'Nunca'));?></td><td><?php echo esc_html($k['status']);?></td><td><?php if($k['status']==='active'):?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><?php wp_nonce_field('fieldflow_api_key_revoke');?><input type="hidden" name="action" value="fieldflow_api_key_revoke"><input type="hidden" name="id" value="<?php echo(int)$k['id'];?>"><button class="button">Revogar</button></form><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div>
        <div class="ff-int-card"><h2>Webhooks</h2><div class="ff-scroller"><table class="widefat striped"><thead><tr><th>Nome</th><th>URL</th><th>Eventos</th><th>Estado</th><th>Sucesso</th><th>Falhas</th><th>Ações</th></tr></thead><tbody><?php if(!$hooks):?><tr><td colspan="7">Ainda não existem webhooks.</td></tr><?php else:foreach($hooks as$h):?><tr><td><?php echo esc_html($h['name']);?></td><td><code><?php echo esc_html($h['url']);?></code></td><td><?php echo esc_html(implode(', ',(array)json_decode((string)$h['events_json'],true)));?></td><td><?php echo esc_html($h['status']);?></td><td><?php echo esc_html((string)($h['last_success_at']?:'Nunca'));?></td><td><?php echo(int)$h['consecutive_failures'];?></td><td><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>" style="display:flex;gap:6px;flex-wrap:wrap"><?php wp_nonce_field('fieldflow_webhook_action');?><input type="hidden" name="action" value="fieldflow_webhook_action"><input type="hidden" name="id" value="<?php echo(int)$h['id'];?>"><button class="button" name="do" value="test">Testar</button><?php if($h['status']==='active'):?><button class="button" name="do" value="paused">Pausar</button><?php else:?><button class="button" name="do" value="active">Ativar</button><?php endif;?><button class="button" name="do" value="revoked">Revogar</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div>
        <div class="ff-int-grid"><div class="ff-int-card"><h2>Power BI</h2><p>Usa o conector Web com uma das URLs abaixo e adiciona o header <code>X-FieldFlow-Key</code>.</p><?php foreach(['execution','routes','visits','submissions','stocks']as$d):?><div class="ff-code" style="margin:8px 0"><?php echo esc_html($base.'/powerbi/'.$d.'?client_id=1&limit=500');?></div><?php endforeach;?><p>Para atualização incremental, envia <code>updated_since</code> e guarda <code>next_cursor</code>.</p></div><div class="ff-int-card"><h2>API de leitura</h2><div class="ff-code"><?php echo esc_html($base.'/resources/locations?client_id=1&limit=100');?></div><p>Recursos: <?php echo esc_html(implode(', ',array_keys(PublicQueryService::resourceCapabilities())));?>.</p><p><a class="button" href="<?php echo esc_url($base.'/schema');?>" target="_blank">Abrir schema</a></p></div></div>
        <div class="ff-int-card"><h2>Entregas recentes</h2><div class="ff-scroller"><table class="widefat striped"><thead><tr><th>Quando</th><th>Webhook</th><th>Evento</th><th>Estado</th><th>Tentativas</th><th>HTTP</th><th></th></tr></thead><tbody><?php if(!$deliveries):?><tr><td colspan="7">Sem entregas.</td></tr><?php else:foreach($deliveries as$d):?><tr><td><?php echo esc_html($d['created_at']);?></td><td><?php echo esc_html($d['webhook_name']);?></td><td><?php echo esc_html($d['event_name']);?></td><td><?php echo esc_html($d['status']);?></td><td><?php echo(int)$d['attempt_count'];?></td><td><?php echo(int)$d['response_code'];?></td><td><?php if(in_array($d['status'],['failed','retry'],true)):?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><?php wp_nonce_field('fieldflow_webhook_action');?><input type="hidden" name="action" value="fieldflow_webhook_action"><input type="hidden" name="id" value="<?php echo(int)$d['id'];?>"><button class="button" name="do" value="retry">Repetir</button></form><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div>
        </div><?php
    }
    public static function renderSummary():void{echo '<div class="notice notice-info inline"><p><strong>API Pública v1 e Webhooks:</strong> gere chaves isoladas, endpoints Power BI e entregas assinadas na nova área. <a class="button button-small" href="'.esc_url(admin_url('admin.php?page='.self::SLUG)).'">Abrir API Pública e Webhooks</a></p></div>';}
}
